class Solution {
  private static long gcd(long a, long b) {
    while (b != 0) {
      long t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  public int minimumIncrements(int[] nums, int[] target) {
    int t = target.length, full = (1 << t) - 1;
    long[] lcm = new long[full + 1];
    for (int mask = 1; mask <= full; mask++) {
      long l = 1;
      for (int i = 0; i < t; i++) if ((mask >> i & 1) != 0) l = l / gcd(l, target[i]) * target[i];
      lcm[mask] = l;
    }
    long INF = Long.MAX_VALUE / 4;
    long[] dp = new long[full + 1];
    java.util.Arrays.fill(dp, INF);
    dp[0] = 0;
    long[] cost = new long[full + 1];
    for (int x : nums) {
      for (int mask = 1; mask <= full; mask++) cost[mask] = (lcm[mask] - x % lcm[mask]) % lcm[mask];
      long[] nd = dp.clone();
      for (int mask = 0; mask <= full; mask++) {
        if (dp[mask] >= INF) continue;
        for (int sub = 1; sub <= full; sub++) {
          int nm = mask | sub;
          if (nm == mask) continue;
          nd[nm] = Math.min(nd[nm], dp[mask] + cost[sub]);
        }
      }
      dp = nd;
    }
    return (int) dp[full];
  }
}
